$retries = 0
while ($retries -lt 60) {
    try {
        $response = Invoke-WebRequest -Uri "https://localhost:44317" -SkipCertificateCheck -ErrorAction Stop
        if ($response.StatusCode -eq 200) {
            Write-Host "✓ Umbraco is responding"
            exit 0
        }
    } catch {
        $retries++
        if ($retries % 10 -eq 0) {
            Write-Host "Waiting... ($retries/60 seconds)"
        }
        Start-Sleep -Seconds 1
    }
}
Write-Host "✗ Umbraco did not start within 60 seconds"
exit 1

