@using ContentModels = Umbraco.Cms.Core.Models.PublishedContent;
@{
    Layout = null;
}
<!DOCTYPE html>
<html>
<head>
    <title>@Model.Value("title")</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-white">
    <div class="container mx-auto px-4 py-8">
        <h1 class="text-4xl font-bold mb-8">@Model.Value("title")</h1>
        @await Html.GetBlockGridHtmlAsync(Model, "blocks")
    </div>
    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</body>
</html>

