@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<ContentModels.BlogPost>
@using ContentModels = Umbraco.Cms.Core.Models.PublishedContent;
@{
    Layout = null;
}
<!DOCTYPE html>
<html>
<head>
    <title>@Model.Value("title")</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-white">
    <div class="container mx-auto px-4 py-8">
        <article>
            <h1 class="text-4xl font-bold mb-4">@Model.Value("title")</h1>
            <div class="text-gray-600 mb-6">
                <span class="mr-4">@Model.Value("date")</span>
            </div>
            @if (Model.Value("excerpt") != null)
            {
                <p class="text-lg text-gray-700 mb-6">@Model.Value("excerpt")</p>
            }
            <div class="prose mb-8">
                @await Html.GetBlockGridHtmlAsync(Model, "blocks")
            </div>
        </article>
    </div>
    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</body>
</html>

