$retries = 0
while ($retries -lt 120) {
    $procCount = @(Get-Process dotnet -ErrorAction SilentlyContinue).Count
    if ($procCount -gt 0) {
        try {
            $response = Invoke-WebRequest -Uri "http://localhost:41576" -ErrorAction SilentlyContinue
            Write-Host "✓ Umbraco is running, generating models..."
            Start-Sleep -Seconds 5
            exit 0
        } catch {}
    }
    $retries++
    if ($retries % 20 -eq 0) {
        Write-Host "Waiting... ($retries/120 seconds)"
    }
    Start-Sleep -Seconds 1
}
Write-Host "✓ Waited for startup"

