@inherits UmbracoViewPage<BlockGridItem<ImageBlock>>
@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Cms.Core.Models.Blocks
@{
    var image = Model.Content.Image?.FirstOrDefault();
    var imageUrl = image?.GetCropUrl(width: 800, height: 600);
    var model = new ImageBlockModel
    {
        ImageUrl = imageUrl,
        Caption = Model.Content.Caption
    };
}
@await Component.InvokeAsync("ImageBlock", new { model })

