@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<Umbraco.Bench.Umbraco.Models.BlogPost>
@using Umbraco.Bench.Umbraco.Models
@{
    Layout = null;
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>@Model.Title</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-white">
    <div class="container mx-auto px-4 py-12">
        <article>
            <h1 class="text-4xl font-bold mb-4">@Model.Title</h1>
            <div class="text-gray-600 mb-6">
                @Model.Value("date")
            </div>
            @if (!string.IsNullOrEmpty(Model.Excerpt))
            {
                <p class="text-lg text-gray-700 mb-6">@Model.Excerpt</p>
            }
            <div class="prose max-w-none">
                @await Html.GetBlockGridHtmlAsync(Model, "blocks")
            </div>
        </article>
    </div>
    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</body>
</html>

