@model Umbraco.Bench.Umbraco.Models.Blocks.ImageBlockModel
@if (!string.IsNullOrEmpty(Model?.ImageUrl))
{
    <figure class="my-8">
        <img src="@Model.ImageUrl" alt="@Model.Caption" class="w-full rounded-lg" />
        @if (!string.IsNullOrEmpty(Model.Caption))
        {
            <figcaption class="text-sm text-gray-600 mt-2 text-center">@Model.Caption</figcaption>
        }
    </figure>
}

@model Umbraco.Bench.Umbraco.Models.Blocks.QuoteBlockModel
@if (!string.IsNullOrEmpty(Model?.Quote))
{
    <blockquote class="border-l-4 border-blue-600 pl-4 py-4 my-8 italic text-gray-700 text-lg">
        <p>@Model.Quote</p>
        @if (!string.IsNullOrEmpty(Model.Author))
        {
            <footer class="text-sm font-semibold text-gray-600 mt-2">— @Model.Author</footer>
        }
    </blockquote>
}

